WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM transactions), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN amount >= 3300 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, AVG(island_id) FILTER (WHERE txn_type = 'FEE') AS fee_avg_island_id, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, MAX(amount) FILTER (WHERE merchant = 'Lazada') AS lazada_max_amount FROM islands GROUP BY CASE WHEN amount >= 3300 THEN 'LARGE' ELSE 'SMALL' END HAVING MAX(amount) FILTER (WHERE merchant = 'Lazada') > 0 ORDER BY span_minutes ASC NULLS LAST;
